  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that starts before and ends inside an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Straddling');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that fully contains an active booking', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Engulfing');
    expect(response.statusCode).toBe(409);
  });

  it('rejects a booking shorter than 30 minutes', async () => {
    const response = await book(24, 24.25, 'Too short');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking longer than 8 hours', async () => {
    const response = await book(24, 33, 'Too long');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking whose end is not after its start', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking that starts in the past', async () => {
    const response = await book(-1, 1, 'Already started');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking for a room that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: 'missing', userId, title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects a booking for a user that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects an update that would overlap another active booking', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('allows an update that keeps the same schedule', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(200);
  });

  it('rejects an update that shrinks a booking below 30 minutes', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { endsAt: inHours(24.1) },
    });
    expect(response.statusCode).toBe(400);
  });

  it('rejects an update moving a booking to a room that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { roomId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects an update moving a booking to a user that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { userId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('allows renaming a booking without touching its schedule even after it started', async () => {
    const created = await book(1, 2);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { title: 'Renamed mid-flight' },
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().title).toBe('Renamed mid-flight');
  });
});

